const endpoint='https://graphql.anilist.co',jikanEndpoint='https://api.jikan.moe/v4',grid=document.querySelector('#animeGrid'),loading=document.querySelector('#loading'),title=document.querySelector('#resultsTitle'),subtitle=document.querySelector('#resultsSubtitle'),dialog=document.querySelector('#animeDialog'),dialogContent=document.querySelector('#dialogContent'),favoritesKey='sempai-anime-favorites';let currentPage=1,activeGenre=null,activeSearch='',currentItems=[];const query=`query ($page: Int, $search: String, $genre: String) { Page(page: $page, perPage: 12) { pageInfo { hasNextPage } media(type: ANIME, isAdult: false, search: $search, genre: $genre, sort: TRENDING_DESC) { id title { romaji english native } coverImage { large } averageScore episodes format status seasonYear genres description(asHtml: false) } } }`;
const favorites=()=>JSON.parse(localStorage.getItem(favoritesKey)||'[]'),setFavorites=v=>{localStorage.setItem(favoritesKey,JSON.stringify(v));updateFavoriteCount()},updateFavoriteCount=()=>document.querySelector('#favoriteCount').textContent=favorites().length,animeTitle=a=>a.title.english||a.title.romaji||a.title.native,escapeHtml=(text='')=>{const el=document.createElement('div');el.textContent=text;return el.innerHTML},toast=message=>{const box=document.querySelector('#toast');box.textContent=message;box.classList.add('show');setTimeout(()=>box.classList.remove('show'),2500)},setLoading=value=>loading.hidden=!value;
function renderCards(items){if(!items.length){grid.innerHTML='<div class="empty">Aucun anime trouvé. Essaie un autre titre ou une autre humeur.</div>';return}const html=items.map(a=>`<article class="anime-card" data-id="${a.id}" tabindex="0"><div class="cover">${a.coverImage?.large?`<img src="${a.coverImage.large}" alt="Affiche de ${escapeHtml(animeTitle(a))}" loading="lazy">`:''}<span class="score">★ ${a.averageScore?Math.round(a.averageScore/10)+'/10':'—'}</span></div><div class="card-info"><h3>${escapeHtml(animeTitle(a))}</h3><p>${a.format||'Anime'} · ${a.episodes||'?'} ép.</p></div></article>`).join('');currentPage===1?grid.innerHTML=html:grid.insertAdjacentHTML('beforeend',html)}
