function normalizeJikan(a){return{id:a.mal_id,title:{romaji:a.title,english:a.title_english,native:a.title_japanese},coverImage:{large:a.images?.jpg?.large_image_url},averageScore:a.score?Math.round(a.score*10):null,episodes:a.episodes,format:a.type,status:a.status,seasonYear:a.year,genres:(a.genres||[]).map(g=>g.name),description:a.synopsis}}
async function loadJikan({fallback=false}={}){setLoading(true);grid.innerHTML='';try{const url=activeSearch?`${jikanEndpoint}/anime?q=${encodeURIComponent(activeSearch)}&limit=12&sfw`:`${jikanEndpoint}/top/anime?limit=12&sfw`,r=await fetch(url);if(!r.ok)throw Error();const p=await r.json();currentItems=(p.data||[]).map(normalizeJikan);currentPage=1;renderCards(currentItems);document.querySelector('#loadMore').hidden=true;subtitle.textContent=fallback?'AniList est momentanément indisponible : voici les données MyAnimeList via Jikan.':'Les incontournables MyAnimeList, via Jikan.'}catch(e){grid.innerHTML='<div class="empty">Impossible de joindre AniList ou Jikan pour le moment. Réessaie dans quelques instants.</div>'}finally{setLoading(false)}}
function openAnime(id){const a=currentItems.find(x=>x.id===Number(id));if(!a)return;const saved=favorites().includes(a.id);dialogContent.innerHTML=`<div class="detail"><img class="detail-cover" src="${a.coverImage?.large||''}" alt=""><div><p class="eyebrow">${escapeHtml(a.format||'Anime')} ${a.seasonYear?'· '+a.seasonYear:''}</p><h2>${escapeHtml(animeTitle(a))}</h2><p class="meta">★ ${a.averageScore?Math.round(a.averageScore/10)+'/10':'Pas encore noté'} · ${a.episodes||'Nombre d’épisodes inconnu'} épisodes · ${escapeHtml(a.status||'')}</p><div class="tags">${(a.genres||[]).map(t=>`<span>${escapeHtml(t)}</span>`).join('')}</div><p class="description">${escapeHtml((a.description||'Description indisponible.').replace(/\n/g,' '))}</p><button class="fav-detail" data-favorite="${a.id}">${saved?'♥ Retirer de ma liste':'♡ Ajouter à ma liste'}</button></div></div>`;dialog.showModal()}
function toggleFavorite(id){const v=favorites(),i=v.indexOf(Number(id));i===-1?(v.push(Number(id)),toast('Ajouté à ta liste !')):(v.splice(i,1),toast('Retiré de ta liste.'));setFavorites(v);dialog.close()}
function startSearch(){activeSearch=document.querySelector('#searchInput').value.trim();if(!activeSearch){toast('Écris le titre d’un anime.');return}activeGenre=null;document.querySelectorAll('#moodGrid button').forEach(x=>x.classList.remove('active'));currentPage=1;title.textContent=`Résultats pour « ${activeSearch} »`;subtitle.textContent='Découvre les anime correspondants.';loadAnime();document.querySelector('#tendance').scrollIntoView({behavior:'smooth',block:'start'})}
document.querySelector('#moodGrid').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;document.querySelectorAll('#moodGrid button').forEach(x=>x.classList.remove('active'));b.classList.add('active');activeGenre=b.dataset.genre;activeSearch='';currentPage=1;title.textContent=b.dataset.label;subtitle.textContent=`Une sélection ${b.dataset.genre.toLowerCase()} rien que pour toi.`;loadAnime();document.querySelector('#tendance').scrollIntoView({behavior:'smooth',block:'start'})});document.querySelector('#searchButton').addEventListener('click',startSearch);document.querySelector('#searchInput').addEventListener('keydown',e=>{if(e.key==='Enter')startSearch()});grid.addEventListener('click',e=>{const c=e.target.closest('.anime-card');if(c)openAnime(c.dataset.id)});grid.addEventListener('keydown',e=>{const c=e.target.closest('.anime-card');if(c&&e.key==='Enter')openAnime(c.dataset.id)});document.querySelector('#closeDialog').addEventListener('click',()=>dialog.close());dialogContent.addEventListener('click',e=>{const b=e.target.closest('[data-favorite]');if(b)toggleFavorite(b.dataset.favorite)});document.querySelector('#loadMore').addEventListener('click',()=>{currentPage++;loadAnime({append:true})});document.querySelector('#jikanButton').addEventListener('click',()=>{activeSearch='';activeGenre=null;title.textContent='Les incontournables MyAnimeList';loadJikan();document.querySelector('#tendance').scrollIntoView({behavior:'smooth'})});document.querySelector('#favoritesButton').addEventListener('click',()=>{const ids=favorites();if(!ids.length){toast('Ta liste est encore vide.');return}const saved=currentItems.filter(x=>ids.includes(x.id));if(saved.length){title.textContent='Ma liste';subtitle.textContent='Les anime que tu veux regarder.';grid.innerHTML='';currentPage=1;renderCards(saved);document.querySelector('#loadMore').hidden=true;document.querySelector('#tendance').scrollIntoView({behavior:'smooth'})}else toast('Ouvre un anime récent pour voir ta liste.')});
async function withButton(b,task){b.disabled=true;const label=b.textContent;b.textContent='Chargement…';try{await task()}catch(e){toast('Ce service est indisponible pour le moment.')}finally{b.disabled=false;b.textContent=label}}
